aerialsunsetflyover.glsl:
#version 300 es
precision highp float;

uniform float time;
uniform vec2 resolution;
uniform vec2 fullResolution;

out vec4 fragColor;

#define TAU 6.283185307179586
#define PI 3.141592653589793

uniform float speed;          // 0.1-5.0, forward flight speed through terrain
uniform float terrainScale;   // 0.5-10.0, scale of terrain features
uniform float colorSaturation;// 0.0-2.0, vibrancy of terrain color bands
uniform float horizonHaze;    // 0.0-3.0, atmospheric fog density at horizon
uniform float lensIntensity;  // 0.0-2.0, strength of sun corona and lens flare
uniform float complexity;     // 2.0-7.0, FBM octave count for terrain detail

float hash11(float p) {
    p = fract(p * 0.1031);
    p *= p + 33.33;
    p *= p + p;
    return fract(p);
}

float hash21(vec2 p) {
    vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973));
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

vec2 hash22(vec2 p) {
    vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973));
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.xx + p3.yz) * p3.zy);
}

float valueNoise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    vec2 u = f * f * (3.0 - 2.0 * f);
    float a = hash21(i + vec2(0.0, 0.0));
    float b = hash21(i + vec2(1.0, 0.0));
    float c = hash21(i + vec2(0.0, 1.0));
    float d = hash21(i + vec2(1.0, 1.0));
    return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

float gradNoise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    vec2 u = f * f * (3.0 - 2.0 * f);
    vec2 ga = hash22(i + vec2(0.0, 0.0)) * 2.0 - 1.0;
    vec2 gb = hash22(i + vec2(1.0, 0.0)) * 2.0 - 1.0;
    vec2 gc = hash22(i + vec2(0.0, 1.0)) * 2.0 - 1.0;
    vec2 gd = hash22(i + vec2(1.0, 1.0)) * 2.0 - 1.0;
    float va = dot(ga, f - vec2(0.0, 0.0));
    float vb = dot(gb, f - vec2(1.0, 0.0));
    float vc = dot(gc, f - vec2(0.0, 1.0));
    float vd = dot(gd, f - vec2(1.0, 1.0));
    return 0.5 + 0.5 * mix(mix(va, vb, u.x), mix(vc, vd, u.x), u.y);
}

// FBM terrain with ridge detail
float fbmTerrain(vec2 p, float octaves) {
    float val = 0.0;
    float amp = 0.5;
    float freq = 1.0;
    float total = 0.0;
    int iOctaves = int(clamp(octaves, 2.0, 7.0));
    for (int i = 0; i < 7; i++) {
        if (i >= iOctaves) break;
        float n = gradNoise(p * freq);
        // Ridge: invert abs
        float ridge = 1.0 - abs(n * 2.0 - 1.0);
        ridge = ridge * ridge;
        val += ridge * amp;
        total += amp;
        freq *= 2.1;
        amp *= 0.48;
    }
    return val / total;
}

// Standard FBM for smooth features
float fbmSmooth(vec2 p, float octaves) {
    float val = 0.0;
    float amp = 0.5;
    float freq = 1.0;
    float total = 0.0;
    int iOctaves = int(clamp(octaves, 2.0, 7.0));
    for (int i = 0; i < 7; i++) {
        if (i >= iOctaves) break;
        val += gradNoise(p * freq) * amp;
        total += amp;
        freq *= 2.0;
        amp *= 0.5;
    }
    return val / total;
}

// Cosine color palette (Inigo Quilez style)
// a, b, c, d are palette coefficients; t is 0-1 gradient position
vec3 cosPalette(float t, vec3 a, vec3 b, vec3 c, vec3 d) {
    return a + b * cos(TAU * (c * t + d));
}

// Terrain color palette: electric purples, teals, volcanic oranges, lime greens
vec3 terrainPalette(float t, float saturation) {
    vec3 a = vec3(0.5, 0.5, 0.5);
    vec3 b = vec3(0.5, 0.5, 0.5);
    vec3 c = vec3(1.0, 0.8, 0.6);
    vec3 d = vec3(0.0, 0.15, 0.4);
    vec3 col = cosPalette(t, a, b, c, d);
    // Boost saturation
    float lum = dot(col, vec3(0.299, 0.587, 0.114));
    return mix(vec3(lum), col, saturation);
}

// Sky gradient: deep violet-indigo top -> magenta band -> warm cream-orange horizon
vec3 skyColor(float horizonT) {
    // horizonT = 0 at top, 1 at horizon
    vec3 topColor    = vec3(0.08, 0.04, 0.22);   // deep violet-indigo
    vec3 midColor    = vec3(0.55, 0.10, 0.42);   // magenta band
    vec3 horizonColor = vec3(1.0, 0.85, 0.55);  // warm cream-orange
    vec3 col;
    if (horizonT < 0.6) {
        col = mix(topColor, midColor, horizonT / 0.6);
    } else {
        col = mix(midColor, horizonColor, (horizonT - 0.6) / 0.4);
    }
    return col;
}

// Atmospheric fog blend: terrain color washes to warm cream-orange with distance
vec3 fogColor(float dist, float hazeDensity) {
    float fogFar  = 300.0;
    float fogNear = 80.0;
    float fogT = clamp((dist - fogNear) / (fogFar - fogNear), 0.0, 1.0);
    fogT = pow(fogT, 0.7) * hazeDensity;
    fogT = clamp(fogT, 0.0, 1.0);
    vec3 haze = vec3(1.0, 0.88, 0.62);
    return haze;
    // caller mixes using fogT
}

float fogFactor(float dist, float hazeDensity) {
    float fogFar  = 300.0;
    float fogNear = 80.0;
    float fogT = clamp((dist - fogNear) / (fogFar - fogNear), 0.0, 1.0);
    fogT = pow(fogT, 0.7);
    return clamp(fogT * hazeDensity, 0.0, 1.0);
}

// Soft sun disc + corona
vec3 sunEffect(vec2 uv, vec2 sunPos, float intensity) {
    float d = length(uv - sunPos);
    float disc = smoothstep(0.04, 0.01, d);
    float corona = exp(-d * 8.0) * 0.6;
    float glow   = exp(-d * 2.5) * 0.4;
    vec3 sunCol  = vec3(1.0, 0.95, 0.75);
    vec3 coronaCol = vec3(1.0, 0.75, 0.35);
    return (disc * sunCol + corona * coronaCol + glow * vec3(1.0, 0.70, 0.30)) * intensity;
}

// Horizontal lens streak
vec3 lensStreak(vec2 uv, vec2 sunPos, float pulse, float intensity) {
    float dy = abs(uv.y - sunPos.y);
    float streak = exp(-dy * dy * 180.0) * 0.35 * (0.6 + 0.4 * pulse);
    float xFade = 1.0 - smoothstep(0.3, 0.8, abs(uv.x - sunPos.x));
    return vec3(1.0, 0.75, 0.3) * streak * xFade * intensity;
}

// Film grain
float filmGrain(vec2 uv, float seed) {
    return hash21(uv * 1000.0 + seed) * 2.0 - 1.0;
}

// Chromatic aberration offset (returns offset amount based on screen edge distance)
float chromaticStrength(vec2 uv) {
    vec2 centered = uv * 2.0 - 1.0;
    float r2 = dot(centered, centered);
    return r2 * r2 * 0.008;
}

// Vignette
float vignette(vec2 uv) {
    vec2 c = uv * 2.0 - 1.0;
    float v = 1.0 - dot(c, c) * 0.35;
    return clamp(v, 0.0, 1.0);
}

void main() {
    vec2 uv = gl_FragCoord.xy / resolution;
    vec2 centered = uv - 0.5;
    centered.x *= resolution.x / resolution.y;

    // ═══════════════════════════════════════════════════════════════════════════
    // LOOPING PRIMITIVES - ALL ANIMATION MUST USE THESE
    // time goes 0→1, so t goes 0→TAU, completing exactly one cycle
    // ═══════════════════════════════════════════════════════════════════════════
    float t = time * TAU;           // Converts time 0→1 to radians 0→TAU
    vec2 timeCircle = vec2(cos(t), sin(t));  // For noise sampling - traces a circle
    float pulse = 0.5 + 0.5 * sin(t);        // 0→1→0 smooth oscillation
    float wave = sin(t);                      // -1→1→-1 smooth oscillation

// ═══════════════════════════════════════════════════════════════════════════
    // CAMERA SETUP
    // ═══════════════════════════════════════════════════════════════════════════

    // Camera position: flying at ~40m altitude with Y-bob
    float camY = 40.0 + wave * 2.5;

    // Lazy lateral banking (roll angle)
    float bankAngle = wave * 0.06;
    float cosBank = cos(bankAngle);
    float sinBank = sin(bankAngle);

    // Ray direction from camera through screen pixel
    // centered.x is already aspect-corrected
    vec2 screenPos = centered; // aspect-corrected centered UV

    // Apply bank rotation to screen space
    vec2 bankedPos;
    bankedPos.x = screenPos.x * cosBank - screenPos.y * sinBank;
    bankedPos.y = screenPos.x * sinBank + screenPos.y * cosBank;

    // FOV ~70 degrees
    float fov = 1.3;
    vec3 rayDir = normalize(vec3(bankedPos.x * fov, bankedPos.y * fov, 1.0));

    // ═══════════════════════════════════════════════════════════════════════════
    // TERRAIN RAYMARCHING
    // ═══════════════════════════════════════════════════════════════════════════

    // Terrain motion: offset XZ using timeCircle for seamless looping
    // timeCircle traces a circle, giving forward+slight-lateral motion
    vec2 terrainOffset = timeCircle * speed * 25.0;

    // Sky vs terrain determination
    // Ground plane intersection: ray from camY downward
    // If rayDir.y >= 0, we're looking at sky

    bool hitTerrain = false;
    float hitDist = 0.0;
    float hitHeight = 0.0;
    vec2 hitXZ = vec2(0.0);

    if (rayDir.y < -0.01) {
        // March along the ray to find where it hits terrain
        // Terrain height is fbmTerrain mapped to ~0-20 units
        float tStep = 0.0;
        float stepSize = 1.0;

        for (int i = 0; i < 80; i++) {
            vec3 pos = vec3(0.0, camY, 0.0) + rayDir * tStep;

            // World XZ position
            vec2 xz = vec2(pos.x, pos.z);

            // Terrain height at this XZ
            vec2 noiseCoord = (xz + terrainOffset) * (terrainScale * 0.08);
            float terrH = fbmTerrain(noiseCoord, complexity) * 18.0;

            float gap = pos.y - terrH;

            if (gap < 0.3) {
                hitTerrain = true;
                hitDist = tStep;
                hitHeight = terrH;
                hitXZ = xz;
                break;
            }

            // Adaptive step: step by gap / 2, min 0.5, max 8
            stepSize = clamp(gap * 0.5, 0.5, 8.0);
            tStep += stepSize;

            if (tStep > 600.0) break;
        }
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // TERRAIN COLOR
    // ═══════════════════════════════════════════════════════════════════════════

    vec3 terrainCol = vec3(0.0);

    if (hitTerrain) {
        // Sample terrain noise at hit point for color variation
        vec2 colorCoord = (hitXZ + terrainOffset) * (terrainScale * 0.08);

        // Multiple noise layers for color bands
        float bandNoise1 = fbmSmooth(colorCoord * 0.7, 4.0);
        float bandNoise2 = fbmSmooth(colorCoord * 1.4 + vec2(3.7, 1.9), 3.0);
        float ridgeVal   = fbmTerrain(colorCoord, complexity);

        // Combine for color palette position
        // Hue drift: add sin(t)*0.4 to palette t-parameter
        float hueDrift = wave * 0.4;
        float palT = bandNoise1 * 0.5 + bandNoise2 * 0.3 + ridgeVal * 0.2 + hueDrift;
        palT = fract(palT); // wrap palette

        terrainCol = terrainPalette(palT, colorSaturation);

        // Ridgeline brightening
        terrainCol += vec3(0.15, 0.12, 0.08) * ridgeVal * ridgeVal;

        // Distance fog
        float fog = fogFactor(hitDist, horizonHaze);
        vec3 haze = vec3(1.0, 0.88, 0.62);
        terrainCol = mix(terrainCol, haze, fog);

        // Perspective depth darkening for near terrain
        float nearDark = 1.0 - smoothstep(0.0, 30.0, hitDist) * 0.0;
        terrainCol *= nearDark;
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // SKY
    // ═══════════════════════════════════════════════════════════════════════════

    // Horizon position on screen (accounting for bank)
    // In ray space: horizon is where rayDir.y == 0
    // Screen Y at horizon: bankedPos.y = 0 → screenPos.y = 0 when no bank

    // Compute sky gradient based on ray direction elevation
    float rayElev = rayDir.y; // -1 to +1, 0 = horizon

    // Map ray elevation to sky gradient: 0 at horizon, 1 at top
    float skyT = clamp(rayElev * 2.5 + 0.0, 0.0, 1.0);
    // horizonT = 1 - skyT (1 at horizon, 0 at top)
    float horizonT = 1.0 - skyT;

    vec3 skyCol = skyColor(horizonT);

    // Extra horizon glow brightening
    float horizonGlow = exp(-abs(rayElev) * 6.0) * horizonHaze * 0.5;
    skyCol += vec3(1.0, 0.85, 0.55) * horizonGlow;

    // ═══════════════════════════════════════════════════════════════════════════
    // SUN DISC + CORONA + LENS FLARE
    // ═══════════════════════════════════════════════════════════════════════════

    // Sun position: just above center-horizon in screen space
    // Sun Y oscillates with sin(t)*0.04
    vec2 sunUV = vec2(0.0, 0.03 + wave * 0.04);
    // Convert sunUV to our centered (aspect-corrected) space
    // sunUV is in normalized centered space
    vec2 sunCentered = sunUV * vec2(resolution.x / resolution.y, 1.0);

    // Distance from ray to sun direction (use bankedPos)
    // For sun we use the screen bankedPos directly
    vec2 sunScreenPos = sunUV; // in non-aspect-corrected centered space

    // Lens pulse: sin(t*2.0) for 2 cycles
    float lensPulse = 0.5 + 0.5 * sin(t * 2.0);

    // Sun effect in centered (aspect-corrected) screen space
    vec2 centeredRaw = uv - 0.5; // not aspect-corrected for sun
    vec3 sunContrib = sunEffect(centeredRaw, sunScreenPos, lensIntensity * 1.4);

    // Lens streak
    vec3 streakContrib = lensStreak(centeredRaw, sunScreenPos, lensPulse, lensIntensity * 1.2);

    // ═══════════════════════════════════════════════════════════════════════════
    // COMPOSE SCENE
    // ═══════════════════════════════════════════════════════════════════════════

    vec3 finalColor;

    if (hitTerrain) {
        finalColor = terrainCol;
    } else {
        finalColor = skyCol;
        // Add sun and lens effects to sky
        finalColor += sunContrib;
        finalColor += streakContrib;
    }

    // ═══════════════════════════════════════════════════════════════════════════
    // POST-PROCESSING
    // ═══════════════════════════════════════════════════════════════════════════

    // Chromatic aberration at screen edges
    float chromaStr = chromaticStrength(uv);
    vec2 chromaOffset = (uv - 0.5) * chromaStr;

    // Sample color channels with slight offset
    // Red channel shifted outward, blue shifted inward
    vec2 uvR = uv + chromaOffset * 2.0;
    vec2 uvB = uv - chromaOffset * 2.0;

    // Recompute simple chroma for edge pixels using sky/terrain blend
    // For efficiency, modulate R and B channels of finalColor
    // by estimated shift (approximation)
    float chromaEdge = chromaStr * 8.0;
    finalColor.r = mix(finalColor.r, finalColor.r * 1.08, chromaEdge);
    finalColor.b = mix(finalColor.b, finalColor.b * 0.92, chromaEdge);

    // Vignette
    float vig = vignette(uv);
    finalColor *= vig;

    // Film grain
    float grain = filmGrain(uv, pulse);
    finalColor += grain * 0.025;

    // Soft tone mapping / exposure
    finalColor = finalColor / (finalColor + 0.8) * 1.5;
    finalColor = clamp(finalColor, 0.0, 1.0);

    // Slight gamma correction
    finalColor = pow(finalColor, vec3(0.9));

fragColor = vec4(finalColor, 1.0);
}
